import React, { useState, useEffect } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';

const links = ['Features', 'Demo', 'How it works', 'Pricing', 'Download'];

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const handler = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handler);
    return () => window.removeEventListener('scroll', handler);
  }, []);

  return (
    <motion.nav
      initial={{ y: -80, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.6, ease: 'easeOut' }}
      style={{
        position: 'fixed', top: 0, left: 0, right: 0, zIndex: 100,
        padding: '0 24px',
        background: scrolled ? 'rgba(10,10,15,0.85)' : 'transparent',
        backdropFilter: scrolled ? 'blur(20px)' : 'none',
        borderBottom: scrolled ? '1px solid rgba(255,255,255,0.06)' : 'none',
        transition: 'all 0.3s ease',
      }}
    >
      <div className="container" style={{ display: 'flex', alignItems: 'center', height: 64, gap: 32 }}>
        {/* Logo */}
        <motion.a
          href="#"
          style={{ display: 'flex', alignItems: 'center', gap: 10, textDecoration: 'none' }}
          whileHover={{ scale: 1.03 }}
        >
          <span style={{ fontSize: 24 }}>🪄</span>
          <span style={{ fontSize: 18, fontWeight: 800, color: '#f1f5f9', letterSpacing: '-0.5px' }}>
            Code<span className="gradient-text">Whisper</span>
          </span>
        </motion.a>

        {/* Nav links */}
        <div style={{ display: 'flex', gap: 4, marginLeft: 'auto' }}>
          {links.map((link) => (
            <motion.a
              key={link}
              href={`#${link.toLowerCase().replace(/\s+/g, '-')}`}
              style={{
                color: 'rgba(241,245,249,0.6)',
                textDecoration: 'none',
                fontSize: 14,
                fontWeight: 500,
                padding: '6px 14px',
                borderRadius: 8,
                transition: 'color 0.2s',
              }}
              whileHover={{ color: '#f1f5f9', backgroundColor: 'rgba(255,255,255,0.06)' }}
            >
              {link}
            </motion.a>
          ))}
        </div>

        {/* CTA */}
        <motion.a
          href="https://github.com/YOUR_USERNAME/CodeWhisper/releases"
          target="_blank"
          rel="noreferrer"
          style={{
            background: 'linear-gradient(135deg, #7c3aed, #06b6d4)',
            color: '#fff',
            textDecoration: 'none',
            fontSize: 14,
            fontWeight: 600,
            padding: '8px 20px',
            borderRadius: 10,
            boxShadow: '0 0 20px rgba(124,58,237,0.4)',
          }}
          whileHover={{ scale: 1.05, boxShadow: '0 0 30px rgba(124,58,237,0.6)' }}
          whileTap={{ scale: 0.97 }}
        >
          Download Free
        </motion.a>
      </div>
    </motion.nav>
  );
}
